SET
  @OperationKey_37f1fe1e104a = N'Accounting.RaiseFinanceExceptions'
SET
  @CategoryID_37f1fe1e104a = 'BF08299C-0F79-466A-97DC-9ECA2F28760A'
SET
  @Description_37f1fe1e104a = N'Raise finance exceptions from a consuming app''s detector. Idempotent on (TypeCode, DedupeKey): an existing row is returned with Created false. On an Open row the creator fields (SourceCreatedByUserID, CreatorUnresolved) and the summary are refreshed from the raise, so a creator identified later (for example a login linked afterwards) unlocks it; nothing else changes, and Reviewed or Corrected rows are never touched. An inactive type is skipped. An unknown type code or entity name, or a malformed entry, fails the whole call and writes nothing. Joins the caller''s transaction when there is one, so a raise made during a save commits or rolls back with it. Requires the system user when called through the API: the raise names who created the source record, which decides who may clear it, so only server code (the consuming apps'' in-process detectors) may raise.'
SET
  @InputTypeName_37f1fe1e104a = N'AccountingRaiseFinanceExceptionsInput'
SET
  @InputTypeDefinition_37f1fe1e104a = N'/**
 * Input for `Accounting.RaiseFinanceExceptions`.
 *
 * NO import statements — definitions are emitted verbatim.
 */
export interface AccountingFinanceExceptionToRaise {
    /** A `FinanceExceptionType.Code`. Unknown codes fail the whole call. */
    TypeCode: string;
    /** MJ entity name of the source record (e.g. `MJ_BizApps_Orders: Order Lines`), resolved to SourceEntityID. */
    SourceEntityName: string;
    /** Primary key of the source record. */
    SourceRecordID: string;
    /** The company whose books are affected. */
    CompanyID: string;
    /** The amount at stake, or null when the detector cannot state one. */
    Amount?: number | null;
    /** The business day the exception belongs to, `YYYY-MM-DD`. Its month is the close it blocks. */
    ExceptionDate: string;
    /** Plain description of what was found in the data. */
    Summary: string;
    /** The detector''s identity for this occurrence. Raising the same (TypeCode, DedupeKey) again returns the existing row; if it is still Open, its creator fields and summary are refreshed from this raise. */
    DedupeKey: string;
    /** The login whose judgement is under review; that user may not clear the exception. */
    SourceCreatedByUserID?: string | null;
    /** True when a creator exists but has no linked login, so separation of duties cannot be checked. */
    CreatorUnresolved?: boolean;
}

export interface AccountingRaiseFinanceExceptionsInput {
    Exceptions: AccountingFinanceExceptionToRaise[];
}
'
SET
  @InputTypeIsArray_37f1fe1e104a = 0
SET
  @OutputTypeName_37f1fe1e104a = N'AccountingRaiseFinanceExceptionsOutput'
SET
  @OutputTypeDefinition_37f1fe1e104a = N'/**
 * Output for `Accounting.RaiseFinanceExceptions`.
 *
 * `Results` has one entry per input exception, in order, when the call succeeds. When any entry
 * names an unknown type or entity, or is malformed, the call fails with `Success: false`, `Errors`
 * names each bad index, and nothing is written.
 *
 * NO import statements — definitions are emitted verbatim.
 */
export interface AccountingRaiseFinanceExceptionResult {
    /** Position of the exception in the input list. */
    Index: number;
    /** The row raised, or the existing row with the same (TypeCode, DedupeKey). Absent when skipped. */
    FinanceExceptionID?: string;
    /** True only when this call wrote the row. */
    Created: boolean;
    /** True when the type is inactive: nothing was written. */
    Skipped?: boolean;
}

export interface AccountingRaiseFinanceExceptionsError {
    /** The input index the error belongs to; absent for a call-level error. */
    Index?: number;
    Code: string;
    Message: string;
}

export interface AccountingRaiseFinanceExceptionsOutput {
    Success: boolean;
    Results: AccountingRaiseFinanceExceptionResult[];
    Errors?: AccountingRaiseFinanceExceptionsError[];
}
'
SET
  @OutputTypeIsArray_37f1fe1e104a = 0
SET
  @ExecutionMode_37f1fe1e104a = N'Sync'
SET
  @RequiredScope_37f1fe1e104a = N'accounting:write'
SET
  @RequiresSystemUser_37f1fe1e104a = 1
SET
  @GenerationType_37f1fe1e104a = N'Manual'
SET
  @CodeApprovalStatus_37f1fe1e104a = N'Approved'
