@Reusable_f9efd8431220 BIT,
@ExternalDataSourceID_f9efd8431220 UNIQUEIDENTIFIER,
@IsMaterialized_f9efd8431220 BIT
SET
  @ID_f9efd8431220 = 'D9AC1C70-41B2-4CD4-8E12-35443312B0E3'
SET
  @Name_f9efd8431220 = N'Finance Exceptions Ready To Close'
SET
  @CategoryID_f9efd8431220 = '126B4161-E7AF-41F6-88B0-0F1F4D8D0867'
SET
  @UserQuestion_f9efd8431220 = N'Which company months still have open finance exceptions, and which are ready to close?'
SET
  @Description_f9efd8431220 = N'Open finance exceptions grouped by company and month of ExceptionDate, with the open amount and how many have been cleared. A month is ready to close when it has no Open exceptions.'
SET
  @SQL_f9efd8431220 = N'-- Month-end readiness from the finance exception list.
-- One row per company and month (the first day of the ExceptionDate''s month) that has any
-- exception. A month is ready to close when it has no Open exceptions: IsReadyToClose = 1,
-- or no row at all.
SELECT
    fe.CompanyID,
    fe.Company,
    DATEFROMPARTS(YEAR(fe.ExceptionDate), MONTH(fe.ExceptionDate), 1) AS ExceptionMonth,
    SUM(CASE WHEN fe.Status = N''Open'' THEN 1 ELSE 0 END) AS OpenCount,
    SUM(CASE WHEN fe.Status = N''Open'' THEN ISNULL(fe.Amount, 0) ELSE 0 END) AS OpenAmount,
    SUM(CASE WHEN fe.Status <> N''Open'' THEN 1 ELSE 0 END) AS ClearedCount,
    CAST(CASE WHEN SUM(CASE WHEN fe.Status = N''Open'' THEN 1 ELSE 0 END) = 0 THEN 1 ELSE 0 END AS BIT) AS IsReadyToClose
FROM [__mj_BizAppsAccounting].vwFinanceExceptions fe
GROUP BY
    fe.CompanyID,
    fe.Company,
    DATEFROMPARTS(YEAR(fe.ExceptionDate), MONTH(fe.ExceptionDate), 1)
ORDER BY
    ExceptionMonth DESC,
    fe.Company;
'
SET
  @TechnicalDescription_f9efd8431220 = N'Aggregates __mj_BizAppsAccounting.vwFinanceExceptions by CompanyID and DATEFROMPARTS(YEAR(ExceptionDate), MONTH(ExceptionDate), 1). OpenCount / OpenAmount count Status = Open; ClearedCount counts Reviewed and Corrected; IsReadyToClose is 1 when OpenCount is 0. A company month with no exceptions has no row and is ready.'
SET
  @Status_f9efd8431220 = N'Approved'
SET
  @QualityRank_f9efd8431220 = 8
SET
  @ExecutionCostRank_f9efd8431220 = 2
SET
  @UsesTemplate_f9efd8431220 = 0
SET
  @AuditQueryRuns_f9efd8431220 = 0
